# Let's manually examine the input/output pairs to understand the transformations
inputs = ['wv', 'bzbxb', 'bwx', 'bgige', 'kj']
outputs = ['xywv', 'bfdubxb', 'bxywx', 'jaiwee', 'kj']

print("Input -> Output:")
for i in range(len(inputs)):
    print(f"{inputs[i]} -> {outputs[i]}")

print("\nAnalyzing differences:")
for i in range(len(inputs)):
    inp, outp = inputs[i], outputs[i]
    print(f"{inp} vs {outp}: ", end="")
    if inp == outp:
        print("No change")
    else:
        # Find where they differ
        min_len = min(len(inp), len(outp))
        diff_pos = -1
        for j in range(min_len):
            if inp[j] != outp[j]:
                diff_pos = j
                break
        if diff_pos == -1:
            if len(inp) < len(outp):
                print(f"Append '{outp[len(inp):]}' at end")
            else:
                print(f"Remove '{inp[len(outp):]}' from end")
        else:
            print(f"Position {diff_pos}: '{inp[diff_pos]}' -> '{outp[diff_pos]}'")

