# Analyze minimal edits for each changed pair
inputs = ['wv', 'bzbxb', 'bwx', 'bgige', 'kj']
outputs = ['xywv', 'bfdubxb', 'bxywx', 'jaiwee', 'kj']

# Manual analysis of minimal edits
pairs = [
    ('wv', 'xywv'),    # Insert x at beginning, w->x
    ('bzbxb', 'bfdubxb'), # z->f at position 1
    ('bwx', 'bxywx'),   # w->x at position 1
    ('bgige', 'jaiwee') # b->j at position 0
]

print("Minimal edits for each pair:")
for i, (inp, outp) in enumerate(pairs):
    print(f"Pair {i}: '{inp}' -> '{outp}'")

    # Find where they differ
    min_len = min(len(inp), len(outp))
    diff_positions = []
    for j in range(min_len):
        if inp[j] != outp[j]:
            diff_positions.append(j)

    # Check if it's insertion/deletion
    if len(outp) > len(inp):
        print(f"  Insertion: Added '{outp[len(inp):]}' at end")
    elif len(inp) > len(outp):
        print(f"  Deletion: Removed '{inp[len(outp):]}' from end")
    else:
        # Same length, check character differences
        if diff_positions:
            for pos in diff_positions:
                print(f"  Position {pos}: '{inp[pos]}' -> '{outp[pos]}'")
        else:
            print("  Same length, no character differences")
    print()

